/**
 * Pair the browser under test with the local host, using a real pairing code.
 *
 * WHY THIS IS A SCRIPT: the browser profile used for verification is disposable
 * (a stale profile caused a Chrome screenshot freeze, so it gets recreated), and
 * a fresh profile has no pairing credential. Every verification run then fails
 * with "no session rows" for a reason that has nothing to do with the code under
 * test. Re-pairing is a prerequisite, not a test, so it lives on its own and
 * prints the outcome instead of pretending to assert something.
 *
 * The code is generated by the real server (`remote-pi-server pair`) and pasted
 * into the real form, so the browser ends up in the same state a person would
 * reach by hand.
 *
 * Usage: node scripts/_pair-browser.mjs "<remotepi://pair?...>" [--wait]
 */

import { attach, evaluate, sleep , APP_ORIGIN } from "./_cdp.mjs";

const code = process.argv[2];
if (code === undefined || !code.startsWith("remotepi://pair")) {
  console.error('usage: node scripts/_pair-browser.mjs "remotepi://pair?..."');
  process.exit(2);
}

const { send } = await attach();
const ev = (expression) => evaluate(send, expression);

await send("Page.navigate", { url: APP_ORIGIN + "/remote-pi/connect" });
await sleep(6000);

// Already paired: nothing to do, and re-pairing would mint a duplicate peer.
const state = await ev(`(() => {
  const t = document.body.innerText || "";
  return JSON.stringify({
    connected: t.includes("host connected"),
    hasPairInput: !!document.querySelector("textarea, input[placeholder*='remotepi']"),
  });
})()`);
const parsed = JSON.parse(state);
if (parsed.connected) {
  console.log("already connected");
  process.exit(0);
}

// The pairing code goes in the textarea (it is a long URI, so the field is
// multi-line); fall back to a single-line input if the layout differs.
const typed = await ev(`(() => {
  const el = document.querySelector("textarea") || document.querySelector("input[placeholder*='remotepi']");
  if (!el) return "no-field";
  const setter = Object.getOwnPropertyDescriptor(
    el instanceof HTMLTextAreaElement ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype,
    "value",
  ).set;
  setter.call(el, ${JSON.stringify(code)});
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
  return "ok";
})()`);
if (typed !== "ok") {
  console.error(`pairing field not found: ${typed}`);
  process.exit(1);
}

// Click the submit control the way a person would, rather than calling the
// client's internals — the point is to exercise the real path.
await ev(`(() => {
  const btn = [...document.querySelectorAll("button")].find((b) => /connect/i.test(b.textContent || ""));
  if (!btn) return "no-button";
  btn.click();
  return "clicked";
})()`);

for (let i = 0; i < 40; i++) {
  await sleep(1000);
  const text = await ev(`document.body.innerText || ""`);
  if (text.includes("host connected")) {
    console.log(`paired after ${String(i + 1)}s`);
    process.exit(0);
  }
}

console.error("pairing did not reach 'host connected' within 40s");
process.exit(1);
